import { useEffect, useState } from "react";
import ProgressBar from "../components/ProgressBar";
import ProgressChart from "../components/ProgressChart";

export default function ProgressPage() {
  const [metrics, setMetrics] = useState({});
  const [streak, setStreak] = useState(0);
  const [xp, setXP] = useState(0);
  const [level, setLevel] = useState(1);
  const [badges, setBadges] = useState([]);
  const [completedDays, setCompletedDays] = useState([]);

  useEffect(() => {
    const quizScore = parseInt(localStorage.getItem("quizScore") || "0");
    const totalQuestions = parseInt(localStorage.getItem("totalQuestions") || "1");
    const quiz = Math.round((quizScore / totalQuestions) * 100);

    const completed = parseInt(localStorage.getItem("lastCompletedCount") || "0");
    const totalTasks = parseInt(localStorage.getItem("lastTotalTasks") || "1");
    const tasks = Math.round((completed / totalTasks) * 100);

    const completedDays = JSON.parse(localStorage.getItem("completedDays") || "[]");
    const currentDay = parseInt(localStorage.getItem("currentDay") || "1");

    const consistency = Math.round((completedDays.length / currentDay) * 100);

    // 🔥 Streak
    let currentStreak = 0;
    for (let i = completedDays.length - 1; i >= 0; i--) {
      if (completedDays[i] === currentDay - currentStreak - 1) currentStreak++;
      else break;
    }

    // 🎮 XP + Level
    const totalXP = parseInt(localStorage.getItem("xp") || "0");
    const level = Math.floor(totalXP / 100) + 1;

    // 🏅 Badges
    const getBadges = () => {
      const b = [];
      if (currentStreak >= 3) b.push("🔥 3 Day Streak");
      if (currentStreak >= 7) b.push("🚀 7 Day Warrior");
      if (quiz >= 80) b.push("🧠 Quiz Master");
      if (consistency >= 70) b.push("📅 Consistency King");
      if (totalXP >= 500) b.push("🏆 Level Grinder");
      return b;
    };

    setMetrics({ quiz, tasks, consistency });
    setStreak(currentStreak);
    setXP(totalXP);
    setLevel(level);
    setBadges(getBadges());
    setCompletedDays(completedDays);
  }, []);

  return (
    <div className="space-y-8">

      {/* HEADER */}
      <div className="rounded-[2rem] border bg-gradient-to-br from-white to-blue-50 p-8 shadow-lg dark:from-slate-800 dark:to-slate-800">
        <h2 className="text-3xl font-semibold">📊 Progress Dashboard</h2>
        <p className="text-slate-600 mt-2">Track your growth and stay motivated 🚀</p>
      </div>

      {/* XP + LEVEL */}
      <div className="grid gap-6 md:grid-cols-2">
        <div className="rounded-[2rem] bg-gradient-to-br from-purple-100 to-purple-50 p-6 shadow-md">
          <h3>🎮 XP</h3>
          <p className="text-3xl font-bold">{xp}</p>
        </div>
        <div className="rounded-[2rem] bg-gradient-to-br from-green-100 to-green-50 p-6 shadow-md">
          <h3>🏆 Level</h3>
          <p className="text-3xl font-bold">{level}</p>
        </div>
      </div>

      {/* GRAPH */}
      <div className="rounded-[2rem] border bg-gradient-to-br from-white to-blue-50 p-6 shadow-md">
        <h3 className="text-lg font-semibold mb-4">📈 Weekly Progress</h3>
        <ProgressChart completedDays={completedDays} />
      </div>

      {/* METRICS */}
      <div className="grid gap-6 xl:grid-cols-3">
        <div className="rounded-[2rem] bg-white p-6 shadow-md">
          <ProgressBar label="Consistency" value={metrics.consistency} />
        </div>
        <div className="rounded-[2rem] bg-white p-6 shadow-md">
          <ProgressBar label="Quiz" value={metrics.quiz} />
        </div>
        <div className="rounded-[2rem] bg-white p-6 shadow-md">
          <ProgressBar label="Tasks" value={metrics.tasks} />
        </div>
      </div>

      {/* STREAK */}
      <div className="rounded-[2rem] bg-gradient-to-br from-teal-100 to-blue-100 p-6 shadow-md">
        <h3>🔥 Streak</h3>
        <p className="text-4xl font-bold">{streak} days</p>
      </div>

      {/* BADGES */}
      <div className="rounded-[2rem] border bg-gradient-to-br from-yellow-100 to-orange-50 p-6 shadow-md">
        <h3 className="text-lg font-semibold mb-4">🏅 Achievements</h3>
        <div className="flex flex-wrap gap-3">
          {badges.length > 0 ? (
            badges.map((badge, i) => (
              <span
                key={i}
                className="px-4 py-2 rounded-full bg-white shadow text-sm font-medium"
              >
                {badge}
              </span>
            ))
          ) : (
            <p className="text-slate-600">No badges yet. Keep going 💪</p>
          )}
        </div>
      </div>

    </div>
  );
}
